/* `arate` is the visual sub-record's byte +0x31, and it is the ALPHA RAMP SLOPE.

   This used to be read as "texture frames per tick in 1/64ths" -- a hypothesis that
   fitted the table's shape and some reference frames, and was wrong. The ROM settles
   both halves of it:

     FRAME. Both draw paths compute the frame from age and life and nothing else:
       RAM 0x80050060 (triangle) and RAM 0x80050298 (quad) do
         lbu a0,0x39 (life total); lbu v0,0x30 (life left); lw v1,0x28(sys) (nframes);
         subu; mult; div  ->  frame = (total - left) * nframes / total
       applied as a T offset of frame * 32 texels down a vertical film strip
       (RAM 0x800500F8..0x8005011C). The whole strip is stretched across the life.

     ALPHA. RAM 0x8004FFC8 does
         lbu a0,0x30 (life left); lbu v0,0x31; mult; lbu v1,0x32; slt
       i.e. alpha = min(lifeLeft * byte31, byte32), written to the vertex at
       RAM 0x80050138. byte32 is the CAP (the value we already store as `a`), and
       byte31 is the slope: full alpha until lifeLeft * slope falls under the cap,
       then a linear fade to nothing. The action integrator at RAM 0x8004F300/0x8004F314
       copies both bytes out of the visual record.

   Values are unchanged, only their meaning: Burn_Fire family 0x32 = 50,
   Explode_* / Debris and most others 0x10 = 16, Lightning 0x04 = 4, Flame_Spout 0x30,
   Fire_S 0x20, LandingSmoke 0x21. */

/* SOURCE_Debris / _Debris2 declare TWO visual variants: identical physics
   (y accel -2.0 per tick^2, elasticity 0.70) with colour 255,255,255 instead of
   the burnt orange of variant 0. Both are on screen in the reference frames
   (p080: dark-red chunks AND white-grey chunks leaving the same blast). */
static const unsigned char EFX_DEBRIS_VAR1[4] = { 255, 255, 255, 255 };
static const float EFX_CHUNK_YACC   = -2.000000f;   /* world units per tick^2 */
static const float EFX_CHUNK_BOUNCE = 0.700000f;   /* visual +0x28 elasticity */
/* The chunk's size step, visual sub-record +0x2C at ROM 0xA2C58, integrated at
   RAM 0x8004EF90. 0.25 / 0.005 is exactly 50 ticks against a 40..50 tick life, so a
   chunk dwindles to nothing as it dies rather than popping out at full size. */
static const float EFX_CHUNK_SHRINK = -0.005000f;

/* One slot = one emitter the anim instantiates. dx/dz are world-unit offsets
   from the anim's own cell; dy is added to the TERRAIN HEIGHT under (x,z), not
   to the anim's y (spawn wrapper RAM 0x801FC918 calls the ground-height fn and
   adds dy to its result). A slot fires when the anim's stage reaches its
   fire_stage: burst sources exactly once, continuous sources every stage. */
struct EfxSlot { unsigned char src, stage; short dx, dy, dz; };
struct EfxRecipe { const char* name; unsigned char nslot; EfxSlot slot[10]; };

